<template>
  <AppShell><header class="page-head"><span class="eyebrow"><ScanFace :size="15" />LEARNING PROFILE</span><h1>学习画像</h1><p>路径、资源和效果评估都依据当前激活画像。</p></header>
    <AsyncState :loading="loading" :error="error" :empty="!profiles.length" empty-text="还没有学习画像" @retry="load"><template #action><RouterLink class="primary-btn" to="/profile/collect">开始对话采集</RouterLink></template>
      <section v-if="current" class="profile-summary"><div class="profile-summary-head"><span><UserRoundCheck :size="25" /></span><div><small>当前画像</small><h2>{{ current.profileName || '我的学习画像' }}</h2><p>v{{ current.version || 1 }} · {{ formatDate(current.updatedAt || current.createdAt) }}</p></div></div><div class="profile-facts"><div><small>学习目标</small><strong>{{ fact('learningGoal','goal','target') }}</strong></div><div><small>薄弱点</small><strong>{{ fact('weaknesses','weakPoints','weakness') }}</strong></div><div><small>资源偏好</small><strong>{{ fact('resourcePreferences','preferences','preference') }}</strong></div><div><small>时间投入</small><strong>{{ fact('timeCommitment','availableTime','studyTime') }}</strong></div></div><RouterLink class="primary-btn full-btn" to="/profile/collect"><RefreshCcw :size="17" />通过对话更新画像</RouterLink></section>
      <section class="section-block"><div class="section-head"><div><h2>画像版本</h2><p>切换后后续路径与推荐随之改变</p></div></div><div class="card-list"><article v-for="item in profiles" :key="item.id" class="item-card profile-item"><span class="item-icon"><ScanFace :size="20" /></span><div><h3>{{ item.profileName || `学习画像 v${item.version||1}` }}</h3><p>{{ formatDate(item.createdAt || item.updatedAt) }}</p></div><button v-if="!isCurrent(item)" class="secondary-btn" :disabled="switching===item.id" @click="activate(item)">{{ switching===item.id?'切换中':'使用' }}</button><span v-else class="status-pill done">当前</span></article></div></section>
    </AsyncState></AppShell>
</template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { RefreshCcw,ScanFace,UserRoundCheck } from 'lucide-vue-next';import { RouterLink } from 'vue-router';import AppShell from '../components/AppShell.vue';import AsyncState from '../components/AsyncState.vue';import { activateProfile,getProfiles } from '../services/api.js';import { activeProfile,formatDate } from '../utils/data.js'
const loading=ref(true),error=ref(''),profiles=ref([]),activeId=ref(0),switching=ref(0);const current=computed(()=>profiles.value.find(isCurrent)||null)
function isCurrent(x){return x.isActive||Number(x.id)===activeId.value}
function valueText(v){if(Array.isArray(v))return v.join('、');if(v&&typeof v==='object')return Object.values(v).filter(x=>typeof x==='string').join('、');return String(v||'待补充')}
function fact(...keys){const source=current.value?.profile||current.value?.profileData||current.value||{};for(const key of keys){if(source[key])return valueText(source[key])}return '待补充'}
async function load(){loading.value=true;error.value='';try{const response=await getProfiles();const body=response?.data||response;profiles.value=body.profiles||[];activeId.value=Number(body.activeReportId||0)}catch(e){error.value=e.message}finally{loading.value=false}}
async function activate(item){switching.value=item.id;try{await activateProfile(item.id);await load()}catch(e){error.value=e.message}finally{switching.value=0}}
onMounted(load)
</script>
<style scoped>.profile-summary{padding:18px;border:1px solid #dce5e0;border-top:3px solid #176f4b;border-radius:7px;background:white}.profile-summary-head{display:grid;grid-template-columns:48px minmax(0,1fr);gap:12px}.profile-summary-head>span{width:48px;height:48px;display:grid;place-items:center;border-radius:6px;background:#e8f3ed;color:#176f4b}.profile-summary-head small{color:#176f4b;font-size:10px;font-weight:800}.profile-summary-head h2{margin:3px 0 0;font-size:17px}.profile-summary-head p{margin:4px 0 0;color:#718078;font-size:10px}.profile-facts{display:grid;grid-template-columns:1fr 1fr;margin:16px 0;border:1px solid #e0e8e4;border-radius:6px;overflow:hidden}.profile-facts>div{min-width:0;padding:12px;border-bottom:1px solid #e0e8e4}.profile-facts>div:nth-child(odd){border-right:1px solid #e0e8e4}.profile-facts>div:nth-last-child(-n+2){border-bottom:0}.profile-facts small,.profile-facts strong{display:block}.profile-facts small{color:#78857e;font-size:9px}.profile-facts strong{display:-webkit-box;margin-top:5px;overflow:hidden;font-size:11px;line-height:1.5;-webkit-box-orient:vertical;-webkit-line-clamp:3}.profile-item{grid-template-columns:40px minmax(0,1fr) auto}.profile-item .secondary-btn{min-height:40px;padding:0 11px;font-size:11px}@media (max-width:360px){.profile-facts{grid-template-columns:1fr}.profile-facts>div,.profile-facts>div:nth-child(odd){border-right:0;border-bottom:1px solid #e0e8e4}.profile-facts>div:nth-last-child(2){border-bottom:1px solid #e0e8e4}}</style>
